import React, {
  forwardRef,
  ReactElement,
  ReactNode,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import { TooltipElement } from './TooltipElement.js';
import type { TooltipPlacement, TooltipDelay } from './types/tooltip.js';
import { _useFocusContext } from '../../core/hooks/useFocusContext.js';
import { _useId } from '../../core/hooks/useId.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { _usePoliteContainer } from '../hooks/_usePoliteContainer.js';
import { _useTooltipState } from '../hooks/useTooltipState.js';

const DEFAULT_OPEN_DELAY = 1000;

// #region Typings
export interface TooltipBaseProps extends DOMProps, StylingProps, DataTestId {
  /** Single child of the tooltip considered to trigger the tooltip element. */
  children: ReactElement;

  /**
   * Defines if the tooltip is disabled or not.
   * @defaultValue false
   */
  disabled?: boolean;

  /**
   * Placement of the tooltip relative to its trigger element.
   * @defaultValue 'top'
   */
  placement?: TooltipPlacement;

  /**
   * Defines if the tooltip should be open initially when used uncontrolled.
   * @defaultValue false
   */
  defaultOpen?: boolean;

  /**
   * Defines if the tooltip is open / closed in a controlled component. In
   * this case, you need to react to `onOpenChange` yourself in order
   * to open and close the tooltip.
   */
  open?: boolean;

  /**
   * Defines the type of delay which is used for the tooltip.
   * @defaultValue 'default'
   */
  delay?: TooltipDelay;

  /** Callback fired when the tooltip opens. */
  onOpenChange?: (isOpen: boolean) => void;

  /** Array of placements to be used as fallback if the tooltip doesn't fit at the specified placement. */
  fallbackPlacements?: TooltipPlacement[];
}

export interface TooltipProps extends TooltipBaseProps {
  /** Text displayed in the tooltip component. */
  text: ReactNode;
}
// #endregion Typings

/**
 * Use the `Tooltip` component to show additional text on hover and click on its trigger element.
 * The trigger element can only be an interactive element, like a button or input.
 */
export const Tooltip = /* @__PURE__ */ forwardRef<HTMLDivElement, TooltipProps>(
  (props: TooltipProps, forwardedRef) => {
    const {
      children,
      text,
      placement = 'top',
      open,
      defaultOpen,
      onOpenChange,
      delay = 'default',
      disabled,
      id: propId,
      fallbackPlacements,
      style: consumerStyle,
      className: consumerClassName,
      'data-testid': dataTestId,
      ...remainingProps
    } = props;

    const generatedId = _useId();
    const id = propId ?? generatedId;

    const {
      isOpen,
      open: openTooltip,
      close: closeTooltip,
    } = _useTooltipState({
      open,
      defaultOpen,
      onOpenChange,
      delay: delay === 'none' ? 0 : DEFAULT_OPEN_DELAY,
    });

    const [tooltipWrapperRef, setTooltipWrapperRef] =
      useState<HTMLSpanElement | null>(null);

    useEffect(
      () => () => closeTooltip(true),
      // eslint-disable-next-line react-hooks/exhaustive-deps
      [],
    );

    // Display contents on the span wrapper is necessary to not interfere with
    // flow content of any layout parent. This will invalidate any
    // getBoundingClientRect() results on the wrapping span, which is why
    // we pass the first child element as a reference to popper.
    const tooltipReferenceElement = useMemo(
      () => tooltipWrapperRef?.children?.[0],
      // eslint-disable-next-line react-hooks/exhaustive-deps
      [tooltipWrapperRef, children],
    );

    // If disabled switches to true at runtime and a tooltip is shown, it should
    // close immediately
    useEffect(() => {
      if (disabled) {
        closeTooltip(true);
      }
    }, [closeTooltip, disabled]);

    const isTooltipHovered = useRef(false);

    const handleKeyDown = useCallback(
      (e: KeyboardEvent) => e.code === 'Escape' && closeTooltip(true),
      [closeTooltip],
    );

    useEffect(() => {
      document.addEventListener('keydown', handleKeyDown);

      return () => {
        document.removeEventListener('keydown', handleKeyDown);
      };
    }, [handleKeyDown]);

    // Create a singleton container with live region attribute to read the contents
    // of the tooltip when it pops up
    const PoliteContainer = _usePoliteContainer();

    const { modality } = _useFocusContext();

    return (
      <>
        <span
          data-testid={dataTestId}
          className={consumerClassName}
          style={{
            // Safari has currently an outstanding issue that results in content
            // being inaccessible, when rendered within a display: contents.
            display: 'contents',
            ...consumerStyle,
          }}
          ref={setTooltipWrapperRef}
          onMouseEnter={() => !disabled && openTooltip()}
          onMouseLeave={() =>
            // we need to wrap this in a requestAnimationFrame to be able to first set the isTooltipHovered state correctly in case the TooltipElement (including the gap) is hovered
            // if we don't, the tooltip is closed before the onMouseOver event of the TooltipElement is triggered (to set the right state), as the onMouseLeave of the tooltip trigger would be queued up afterwards
            requestAnimationFrame(() => {
              if (!disabled && !isTooltipHovered.current) {
                closeTooltip();
              }
            })
          }
          onFocus={() =>
            !disabled &&
            modality !== 'pointer' &&
            modality !== 'touch' &&
            openTooltip(true)
          }
          onBlur={
            () => !disabled && !isTooltipHovered.current && closeTooltip(true) // prevent closing when clicking on the gap
          }
          {...remainingProps}
        >
          {children}
        </span>
        <PoliteContainer>
          {isOpen && (
            <TooltipElement
              ref={forwardedRef}
              triggerElement={tooltipReferenceElement}
              placement={placement}
              fallbackPlacements={fallbackPlacements}
              id={id}
              data-testid={'tooltip-element'}
              onMouseLeave={() => !disabled && closeTooltip()}
              onTooltipHovered={(isHovered: boolean) =>
                (isTooltipHovered.current = isHovered)
              }
            >
              {text}
            </TooltipElement>
          )}
        </PoliteContainer>
      </>
    );
  },
);
(Tooltip as typeof Tooltip & { displayName: string }).displayName = 'Tooltip';
